// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import {
  DataTable,
  TableContainer,
  TableToolbar,
  TableToolbarSearch,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
} from 'carbon-components-react';

const headers = [
  { key: 'name', header: 'Name' },
];

const rows = [
  { id: '1', name: 'Alice' },
  { id: '2', name: 'Bob' },
];

function App() {
  return (
    <DataTable
      rows={rows}
      headers={headers}
      render={({ rows, headers, onInputChange }) => (
        <TableContainer title="Searchbox has no label">
          <TableToolbar>
            {/* No explicit labelText passed here */}
            <TableToolbarSearch onChange={onInputChange} />
          </TableToolbar>
          <Table>
            <TableHead>
              <TableRow>
                {headers.map(h => (
                  <TableHeader key={h.key} {...{}}>
                    {h.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(r => (
                <TableRow key={r.id}>
                  {r.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    />
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
